CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE companies(id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('pg','competitor')), created_at TEXT NOT NULL);
CREATE TABLE brands(id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, slug TEXT NOT NULL, logo_url TEXT, created_at TEXT NOT NULL, UNIQUE(company_id,slug));
CREATE TABLE categories(id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, parent_category_id TEXT REFERENCES categories(id));
CREATE TABLE products(id INTEGER PRIMARY KEY, brand_id TEXT NOT NULL REFERENCES brands(id), category_id TEXT NOT NULL REFERENCES categories(id), name TEXT NOT NULL, normalized_name TEXT NOT NULL, product_family TEXT, description TEXT, image_url TEXT, demo_scope INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(brand_id,category_id,normalized_name,demo_scope));
CREATE TABLE product_variants(id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), identity_key TEXT NOT NULL UNIQUE, sku TEXT, barcode TEXT, variant_name TEXT, size_value REAL, size_unit TEXT, pack_count INTEGER, normalized_quantity REAL, normalized_unit TEXT, original_size TEXT NOT NULL DEFAULT '', subcategory TEXT, purpose TEXT, attributes TEXT NOT NULL DEFAULT '{}', country TEXT NOT NULL DEFAULT 'QA', source_state TEXT NOT NULL, source_reference TEXT, verified INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX variant_barcode ON product_variants(barcode,source_state='DEMO') WHERE barcode IS NOT NULL AND barcode<>'';
CREATE INDEX variant_product ON product_variants(product_id);
CREATE INDEX product_category ON products(category_id,brand_id);
CREATE TABLE retailers(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, country TEXT NOT NULL DEFAULT 'QA', website TEXT, created_at TEXT NOT NULL);
CREATE TABLE retailer_products(id INTEGER PRIMARY KEY, retailer_id TEXT NOT NULL REFERENCES retailers(id), product_variant_id INTEGER NOT NULL REFERENCES product_variants(id), retailer_product_name TEXT NOT NULL, retailer_product_url TEXT, retailer_sku TEXT NOT NULL, image_url TEXT, availability TEXT NOT NULL CHECK(availability IN ('available','out_of_stock','unknown')), source_state TEXT NOT NULL, last_seen_at TEXT NOT NULL, collection_error TEXT);
CREATE UNIQUE INDEX listing_identity ON retailer_products(retailer_id,retailer_sku,source_state='DEMO');
CREATE INDEX listing_variant ON retailer_products(product_variant_id);
CREATE TABLE price_observations(id INTEGER PRIMARY KEY, retailer_product_id INTEGER NOT NULL REFERENCES retailer_products(id), price REAL CHECK(price>0), currency TEXT NOT NULL CHECK(currency='QAR'), observed_at TEXT NOT NULL, source_state TEXT NOT NULL, availability TEXT NOT NULL, source_reference TEXT, collection_run_id TEXT, import_run_id TEXT, event_key TEXT NOT NULL, UNIQUE(retailer_product_id,event_key));
CREATE INDEX observation_latest ON price_observations(retailer_product_id,observed_at DESC,id DESC);
CREATE TRIGGER immutable_price_update BEFORE UPDATE ON price_observations BEGIN SELECT RAISE(ABORT,'Price observations are append-only'); END;
CREATE TRIGGER immutable_price_delete BEFORE DELETE ON price_observations BEGIN SELECT RAISE(ABORT,'Price observations are append-only'); END;
CREATE TABLE competitor_relationships(source_product_variant_id INTEGER NOT NULL REFERENCES product_variants(id), competitor_product_variant_id INTEGER NOT NULL REFERENCES product_variants(id), relationship_type TEXT NOT NULL, match_score REAL NOT NULL CHECK(match_score BETWEEN 0 AND 1), match_reason TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, review_status TEXT NOT NULL DEFAULT 'pending', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(source_product_variant_id,competitor_product_variant_id));
CREATE TABLE data_collection_runs(id TEXT PRIMARY KEY, retailer_id TEXT NOT NULL REFERENCES retailers(id), query TEXT NOT NULL, context TEXT NOT NULL DEFAULT '{}', started_at TEXT, completed_at TEXT, status TEXT NOT NULL, records_found INTEGER NOT NULL DEFAULT 0, records_saved INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, errors TEXT);
CREATE INDEX collection_queue ON data_collection_runs(status,started_at);
CREATE TABLE data_collection_errors(id INTEGER PRIMARY KEY, collection_run_id TEXT NOT NULL REFERENCES data_collection_runs(id), error_type TEXT NOT NULL, product_query TEXT, error_message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE discoveries(id INTEGER PRIMARY KEY, collection_run_id TEXT NOT NULL REFERENCES data_collection_runs(id), product_url TEXT NOT NULL, raw_product TEXT NOT NULL, state TEXT NOT NULL, reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE import_runs(id TEXT PRIMARY KEY, source_state TEXT NOT NULL, dry_run INTEGER NOT NULL, summary TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE import_errors(id INTEGER PRIMARY KEY, import_run_id TEXT NOT NULL REFERENCES import_runs(id), row_number INTEGER NOT NULL, error_message TEXT NOT NULL);
CREATE TABLE import_rows(id INTEGER PRIMARY KEY, import_run_id TEXT NOT NULL REFERENCES import_runs(id), row_number INTEGER NOT NULL, raw_data TEXT NOT NULL);
